{"2:286":[[{"ar":"لَا يُكَلِّفُ","en":"Does not burden","bn":"দায়িত্ব দেন না"},{"ar":"اللّٰهُ","en":"Allah","bn":"আল্লাহ"},{"ar":"نَفۡسًا","en":"any soul","bn":"কোনো ব্যক্তিকে"},{"ar":"اِلَّا وُسۡعَهَا ؕ","en":"except its capacity.","bn":"তার সাধ্যের অতিরিক্ত।"}],[{"ar":"لَهَا","en":"For it is","bn":"তার জন্য রয়েছে"},{"ar":"مَا كَسَبَتۡ","en":"what it has earned,","bn":"যা সে অর্জন করেছে,"}],[{"ar":"وَعَلَيۡهَا","en":"and against it is","bn":"আর তার উপর বর্তায়"},{"ar":"مَا اكۡتَسَبَتۡؕ","en":"what it has earned.","bn":"যা সে কামাই করেছে।"}],[{"ar":"رَبَّنَا","en":"“Our Lord,","bn":"‘হে আমাদের রব,"},{"ar":"لَا تُؤَاخِذۡنَاۤ","en":"do not hold us accountable","bn":"আপনি আমাদেরকে পাকড়াও করবেন না"},{"ar":"اِنۡ نَّسِيۡنَاۤ","en":"if we forget","bn":"যদি আমরা ভুলে যাই"},{"ar":"اَوۡ اَخۡطَاۡنَا ۚ","en":"or make a mistake.","bn":"অথবা ভুল করি।"}],[{"ar":"رَبَّنَا","en":"Our Lord,","bn":"হে আমাদের রব,"},{"ar":"وَلَا تَحۡمِلۡ","en":"and do not lay","bn":"আর চাপিয়ে দেবেন না"},{"ar":"عَلَيۡنَاۤ اِصۡرًا","en":"a burden upon us","bn":"আমাদের উপর বোঝা"},{"ar":"كَمَا حَمَلۡتَهٗ","en":"like that which You laid","bn":"যেমন আপনি চাপিয়েছিলেন"},{"ar":"عَلَى الَّذِيۡنَ","en":"on those","bn":"তাদের উপর"},{"ar":"مِنۡ قَبۡلِنَا ۚ","en":"before us.","bn":"যারা আমাদের পূর্বে ছিল।"}],[{"ar":"رَبَّنَا","en":"Our Lord,","bn":"হে আমাদের রব,"},{"ar":"وَلَا تُحَمِّلۡنَا","en":"and do not burden us","bn":"আর আমাদেরকে বহন করাবেন না"},{"ar":"مَا لَا طَاقَةَ لَنَا بِهٖ ۚ","en":"with what we have no strength to bear.","bn":"যা বহনের সামর্থ্য আমাদের নেই।"}],[{"ar":"وَاعۡفُ عَنَّا","en":"Pardon us,","bn":"আমাদের ত্রুটি মোচন করুন,"},{"ar":"وَاغۡفِرۡ لَنَا","en":"forgive us,","bn":"আমাদেরকে ক্ষমা করুন,"},{"ar":"وَارۡحَمۡنَا","en":"and have mercy on us.","bn":"এবং আমাদের প্রতি দয়া করুন।"}],[{"ar":"اَنۡتَ مَوۡلٰٮنَا","en":"You are our Protector,","bn":"আপনিই আমাদের অভিভাবক,"}],[{"ar":"فَانۡصُرۡنَا","en":"so help us","bn":"অতএব আমাদের সাহায্য করুন"},{"ar":"عَلَى الۡقَوۡمِ","en":"against the people","bn"